/**
 * ДЕКОРЛАР КІТАПХАНАСЫ — плитаның түрлері (Egger, Kronospan, Cleaf, SMart,
 * Byspan, Томский ДСП).
 *
 * НЕГЕ КІТАПХАНА ЖӘНЕ ПРОФИЛЬ БӨЛЕК. Цех 500 декордың бәрін САТЫП АЛМАЙДЫ:
 * ол бес-он декормен жұмыс істейді, ал қоймасында да, бағасында да солар
 * тұрады. Сондықтан кітапхана — ТАҢДАУ ҮШІН тізім, ал цехтың профиліне тек
 * өзі қосқаны түседі (`AddMaterial`). Осылайша смета да, раскрой да цехтың
 * нақты материалымен есептеледі.
 *
 * ⚠ ТҮС — ШАМАМЕН. Ол декордың АТЫНАН шығарылған (дуб → сарғыш, бетон →
 * сұр), себебі нағыз реңк жеткізушінің физикалық үлгісінде ғана болады.
 * Түс тек 3D көрінісіне әсер етеді — деталировкаға да, раскройға да, сметаға
 * да ЕШҚАНДАЙ қатысы жоқ. Цех өз материалын қосқанда түсін дәлдей алады.
 *
 * ⚠ АРТИКУЛ — ӨНДІРУШІНІКІ. Бұл — жеткізушінің каталогындағы ашық деректер
 * (Egger H1145, Kronospan K076 …), сондықтан цех қағазымен салыстыра алады.
 * Бағасы мұнда ЖОҚ әрі болмайды да: ол әр цехта басқа (§6).
 */

export type DecorKind = 'chipboard' | 'mdf' | 'hardboard' | 'other'

export type DecorEntry = {
  id: string
  /** Жеткізушінің каталогындағы толық атауы. */
  name: string
  /** Бренд: тізімді сүзу үшін. Белгісізде — бос жол. */
  brand: string
  /** Артикул (H1145, K076…). Кейбір позицияларда болмайды. */
  code: string
  kind: DecorKind
  /** ⚠ ШАМАМЕН, атынан шығарылған. */
  color: string
  /** Текстурасы бар ма — раскройда деталь бұрылмайды. */
  hasGrain: boolean
}

