/** Кітапханадағы брендтер — сүзгі үшін, кездесу ретімен. */
export const DECOR_BRANDS: string[] = [
  ...new Set(DECOR_LIBRARY.map((d) => d.brand).filter((b) => b !== '')),
]

/**
 * Іздеу: атауы, артикулы және бренді бойынша.
 *
 * Сұраныс БІРНЕШЕ сөзден тұруы мүмкін («egger дуб»), сондықтан сөздер бөлек
 * тексеріледі — цех жадындағы екі белгіні қатар жазады.
 */
export function searchDecors(query: string, brand?: string, limit = 60): DecorEntry[] {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean)
  const out: DecorEntry[] = []
  for (const d of DECOR_LIBRARY) {
    if (brand && d.brand !== brand) continue
    const hay = `${d.name} ${d.code} ${d.brand}`.toLowerCase()
    if (words.every((w) => hay.includes(w))) out.push(d)
    if (out.length >= limit) break
  }
  return out
}

export function findDecor(id: string): DecorEntry | undefined {
  return DECOR_LIBRARY.find((d) => d.id === id)
}
